mapper.insert:

    SELECT
        'REEX'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(RECRUIT_EXAM_NO), LENGTH('REEX' ) + 1)), 0) + 1, 6, '0')
    FROM RECRUITMENT_EXAM

	INSERT INTO RECRUITMENT_EXAM (
		RECRUIT_EXAM_NO
		, PROCESS_NO
		, RECRUIT_EXAM_NAME
		, RECRUIT_EXAM_CUTLINE
		, RECRUIT_EXAM_START_DATE
		, RECRUIT_EXAM_END_DATE
	) VALUES (
		#{recruitExamNo}
		, #{processNo}
		, #{recruitExamName}
		, #{recruitExamCutline}
		, TO_DATE(#{recruitExamStartDate}, 'YYYY-MM-DD HH24:MI')
		, TO_DATE(#{recruitExamEndDate}, 'YYYY-MM-DD HH24:MI')
	)

mapper.update:
UPDATE RECRUITMENT_EXAM SET 
	RECRUIT_EXAM_NAME = #{recruitExamName}
	, RECRUIT_EXAM_CUTLINE = #{recruitExamCutline}
	, RECRUIT_EXAM_START_DATE = TO_DATE(#{recruitExamStartDate}, 'YYYY-MM-DD HH24:MI')
	, RECRUIT_EXAM_END_DATE = TO_DATE(#{recruitExamEndDate}, 'YYYY-MM-DD HH24:MI')
WHERE RECRUIT_EXAM_NO = #{recruitExamNo}
